nationalOccasions.forEach(event=>{const item=catalog[event.id];if(!item||!item.date)return;const [,month,day]=item.date.split('-').map(Number);let occurrence=new Date(today.getFullYear(),month-1,day);occurrence.setHours(0,0,0,0);if(occurrence<today){occurrence=new Date(today.getFullYear()+1,month-1,day);occurrence.setHours(0,0,0,0);}item.date=getLocalDateKey(occurrence);});
const eventDates={};
Object.values(catalog).forEach(item=>{if(item.date){if(!eventDates[item.date])eventDates[item.date]=[];eventDates[item.date].push(item)}});
