function getLocalDateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function parseDateKey(key){const [y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d)}
function formatShortDate(date){return `${monthNames[date.getMonth()].slice(0,3)} ${date.getDate()}`}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
function occasionData(id){return catalog[id]||catalog.generic||catalog.diwali}
function setTheme(id,{manual=true,scroll=false,updateTitle=true}={}){
 if(!catalog[id])id='diwali'; activeId=id; const item=catalog[id]; document.body.dataset.theme=item.theme||'generic'; document.documentElement.style.colorScheme='dark';
 $('heroEyebrow').textContent=item.eyebrow; const heroLines=String(item.heroTitle||'Make every moment glow.').split('\n'); $('heroTitle').innerHTML=heroLines.length>1?`${escapeHtml(heroLines[0])}<br><em>${escapeHtml(heroLines.slice(1).join(' '))}</em>`:`<em>${escapeHtml(heroLines[0])}</em>`; $('heroDescription').textContent=item.heroDesc; if($('heroCardKicker'))$('heroCardKicker').textContent=item.eyebrow; if($('heroCardHindi'))$('heroCardHindi').textContent=item.heroHindi; if($('heroCardTitle'))$('heroCardTitle').textContent=item.card; if($('floatingTop'))$('floatingTop').textContent=`${item.name}, with warmth`; const heroIllustration=$('heroIllustration');if(heroIllustration)heroIllustration.dataset.occasion=id; applyFestivalMotion(id);
 document.body.dataset.occasion=id;
 if(updateTitle)document.title=`${item.name} Wishes & Greeting Cards | WishingASR`;
 document.querySelectorAll('.occasion-card').forEach(card=>card.classList.toggle('selected',card.dataset.id===id));
 if($('occasionSelect') && $('occasionSelect').value!==id)$('occasionSelect').value=id;
 updatePreview(); renderCalendar(); renderUpcoming();
 if(manual){try{sessionStorage.setItem('wishingasr-selected-theme',id)}catch(e){}}
 if(scroll){$('create').scrollIntoView({behavior:'smooth',block:'start'});}
}
