function applyFestivalMotion(id){
 const art=$('heroArtParticles');
 if(!art)return;
 const item=catalog[id]||catalog.diwali;
 const motifs={diwali:['✦','🪔','✧','✨'],holi:['●','✿','🎨','●'],eid:['☾','✧','★','🏮'],christmas:['❄','✦','🎄','❄'],newyear:['✦','✧','✺','🎆'],rakhi:['✧','🧵','✦','♡'],birthday:['🎈','✦','✧','🎉'],wedding:['✿','♡','✧','✦'],anniversary:['♡','✦','✧','♡'],valentine:['♡','♥','✧','🌹'],rose:['🌹','✦','♡','✧'],propose:['💍','♡','✧','✦'],chocolate:['🍫','✦','♡','✧'],teddy:['🧸','♡','✧','✦'],promise:['🤝','✦','♡','✧'],hug:['♡','🫂','✧','✦'],kiss:['💋','♡','✧','♥'],pongal:['☀','🌾','✧','✦'],ganesh:['✦','🌺','ॐ','✧'],navratri:['✦','🌺','✧','🪷'],dussehra:['✦','🏹','✧','🔥'],janmashtami:['🪈','🪷','✧','✦'],baisakhi:['🌾','☀','✧','✦'],buddha:['🪷','☸','✧','✦'],chhath:['☀','🌊','✧','🪷'],republicday:['🇮🇳','✦','🟧','🟩'],independenceday:['🇮🇳','🎆','✦','🟩'],gandhijayanti:['🕊️','☸','✦','🌿'],constitutionday:['📜','⚖️','✦','📘'],nationalunityday:['🤝','🇮🇳','✦','🌈'],nationalyouthday:['🚀','✦','💡','⭐'],votersday:['🗳️','✓','✦','🇮🇳'],scienceday:['🔬','⚛','✦','💡'],technologyday:['⚙️','💡','✦','🚀'],kargilvijaydiwas:['🎖️','🇮🇳','✦','🕊️'],sportsday:['🏅','🏃','✦','⭐'],teachersday:['📚','✎','✦','🍎'],hindidiwas:['अ','📚','✦','✍️'],airforceday:['✈️','☁','✦','🇮🇳'],educationday:['🎓','📖','✦','💡'],childrensday:['🧒','🎈','✦','🌈'],armyday:['🪖','🇮🇳','✦','🎖️'],navyday:['⚓','🌊','✦','🇮🇳'],ambedkarjayanti:['⚖️','📘','✦','💙'],girlchildday:['👧','⭐','✦','💜']};
 const set=motifs[id]||[item.icon,'✦','✧','♡'];
 const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const narrowMotion=window.matchMedia('(max-width:640px)').matches;const tabletMotion=window.matchMedia('(max-width:1024px)').matches;const particleCount=reduceMotion?0:(narrowMotion?3:(tabletMotion?5:8));art.dataset.motionTheme=id;art.innerHTML=Array.from({length:particleCount},(_,i)=>`<span class="motion-particle particle-${i%7}" aria-hidden="true" style="--particle-delay:${(i%11)*-.61}s;--particle-x:${(i*41+7)%94}%;--particle-size:${12+(i%6)*4}px;--particle-duration:${6+(i%7)}s">${set[i%set.length]}</span>`).join('');
 const preview=$('wishPreview'); if(preview){preview.classList.remove('occasion-arrive');void preview.offsetWidth;preview.classList.add('occasion-arrive');}
 const card=$('heroIllustration');if(card){
  const profile=characterCelebrationProfiles[id]||'sparkle';
  card.dataset.celebration=profile;
  card.dataset.occasion=id;
  card.style.setProperty('--occasion-glow',getComputedStyle(document.body).getPropertyValue('--accent').trim()||'#e7c47b');
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  card.classList.remove('illustration-arrive','celebration-change');
  if(!reduced){void card.offsetWidth;card.classList.add('illustration-arrive','celebration-change');}
  const speech=$('characterSpeech');
  if(speech){speech.dataset.occasion=id;}
 }
}

function hinglishWish(item,tone){
 const name=item.name;
 const messages={
  heartfelt:`Happy ${name}! Dil se dua hai ki aapke har din mein khushiyan, apno ka pyaar aur dil ko sukoon dene wale pal hon.`,
  short:`Happy ${name}! Aapki life khushiyon, pyaar aur success se bhari rahe.`,
  poetic:`Har naya pal ek khoobsurat yaad ban jaaye, har muskaan dil ko roshan kare. Happy ${name}!`,
  formal:`Aapko aur aapke parivaar ko ${name} ki dher saari shubhkamnayein. Aapka jeevan sukh, sehat aur samriddhi se bhara rahe.`,
  funny:`Happy ${name}! Khushiyan unlimited, tension minimum aur celebrations full-on hon!`,
  cheerful:`Happy ${name}! Smiles, masti aur khoobsurat yaadon se bhara din ho!`,
  romantic:`Happy ${name}, meri jaan. Aapke saath har pal thoda aur khaas aur har yaad thodi aur khoobsurat lagti hai.`,
  devotional:`Is ${name} par dua hai ki aapke ghar mein sukh-shanti, sehat aur barkat bani rahe.`
 };
 return messages[tone]||messages.heartfelt;
}
function wishText(item,tone,lang){
 if(lang==='hinglish')return hinglishWish(item,tone);
 const map=lang==='hi'?item.hiWishes:item.wishes;
 if(map&&map[tone])return map[tone];
 if(tone==='cheerful')return lang==='hi'?`${item.hi||item.name} के अवसर पर आपके जीवन में ढेर सारी खुशियाँ, मुस्कान और सुंदर यादें आएँ।`:`Wishing you a ${item.name} full of bright smiles, joyful moments, and wonderful surprises!`;
 if(tone==='romantic')return lang==='hi'?`${item.hi} के इस खास अवसर पर आपके रिश्तों में प्रेम, अपनापन और खूबसूरत यादें बनी रहें।`:`May ${item.name} bring you closer to the people you love and create memories worth keeping.`;
 return (map&&map.heartfelt)||(item.wishes&&item.wishes.heartfelt)||'Wishing you joy, peace, and beautiful moments.';
}
